def task_kind(tid):
    if tid == "lab":
        return "lab"
    for pre, k in (("pilot_", "pilot"), ("solve_", "solve"), ("tstep_", "tstep"), ("tprod_", "tprod")):
        if tid.startswith(pre):
            return k
    return tid
